"""DHCP section isc_dhcpd from ISC DHCP and Kea, local checks for NetBird (PR #81)."""
import json
import unittest
from unittest import mock

from harness import FakeOPNsense, config_xml, load_agent, local_lines

NOW = 1_790_000_000

KEA_ON = "<OPNsense><Kea><dhcp4><general><enabled>1</enabled></general></dhcp4></Kea></OPNsense>"
KEA_OFF = KEA_ON.replace("<enabled>1</enabled>", "<enabled>0</enabled>")
# as generated by OPNsense (pure JSON)
KEA_CONF = json.dumps({"Dhcp4": {"interfaces-config": {"interfaces": ["vtnet0"]}, "subnet4": [
    {"id": 1, "subnet": "10.91.0.0/24", "pools": [{"pool": "10.91.0.100 - 10.91.0.199"}]},
    {"id": 2, "subnet": "10.92.0.0/24", "pools": [{"pool": "10.92.0.0/25"}]},
]}})
# the sample file of a fresh OPNsense, with comments
KEA_SAMPLE = "// This is a basic configuration for the Kea DHCPv4 server.\n{ \"Dhcp4\": { \"subnet4\": [] } }\n"
LEASE_HEADER = "address,hwaddr,client_id,valid_lifetime,expire,subnet_id,fqdn_fwd,fqdn_rev,hostname,state,user_context,pool_id\n"


def lease(ip, expire, state=0, lifetime=4000):
    return f"{ip},52:54:00:00:00:01,,{lifetime},{expire},1,0,0,host,{state},,0\n"


ISC_CONFIG = """<dhcpd><lan><enable>1</enable><range><from>192.168.1.100</from><to>192.168.1.199</to></range></lan></dhcpd>"""
ISC_LEASES = """lease 192.168.1.100 {
  starts 4 2026/11/12 10:00:00;
  binding state active;
}
lease 192.168.1.101 {
  starts 4 2026/11/12 10:00:00;
  binding state free;
}
"""


def run_dhcp(config, files, lease_files=()):
    files = dict(files)
    with FakeOPNsense(config_xml(config), files=files, now=NOW) as checker:
        with mock.patch("glob.glob", return_value=list(lease_files)):
            return checker.check_dhcp()


def section(lines):
    pools = lines[lines.index("[pools]") + 1:lines.index("[leases]")]
    leases = lines[lines.index("[leases]") + 1:]
    return pools, leases


class TestKea(unittest.TestCase):
    def test_pools_and_active_leases(self):
        files = {"/usr/local/etc/kea/kea-dhcp4.conf": KEA_CONF,
                 "/var/db/kea/kea-leases4.csv": LEASE_HEADER + lease("10.91.0.100", NOW + 3000)
                 + lease("10.91.0.101", NOW - 10) + lease("10.91.0.102", NOW + 3000, state=1)}
        lines = run_dhcp(KEA_ON, files, ["/var/db/kea/kea-leases4.csv"])
        self.assertEqual(lines[0], "<<<isc_dhcpd>>>")
        pools, leases = section(lines)
        self.assertEqual(pools, ["10.91.0.100\t10.91.0.199", "10.92.0.1\t10.92.0.126"])
        self.assertEqual(leases, ["10.91.0.100"])

    def test_last_line_of_an_address_wins(self):
        """kea appends changes: a released lease (expire <= now) must not stay active."""
        old = LEASE_HEADER + lease("10.91.0.100", NOW + 3000) + lease("10.91.0.110", NOW + 3000)
        new = LEASE_HEADER + lease("10.91.0.100", NOW - 1, lifetime=0) + lease("10.91.0.120", NOW + 3000)
        files = {"/usr/local/etc/kea/kea-dhcp4.conf": KEA_CONF,
                 "/var/db/kea/kea-leases4.csv.2": old, "/var/db/kea/kea-leases4.csv": new,
                 "/var/db/kea/kea-leases4.csv.output": LEASE_HEADER + lease("10.91.0.130", NOW + 3000)}
        lines = run_dhcp(KEA_ON, files, ["/var/db/kea/kea-leases4.csv", "/var/db/kea/kea-leases4.csv.2",
                                         "/var/db/kea/kea-leases4.csv.output"])
        self.assertEqual(section(lines)[1], ["10.91.0.110", "10.91.0.120"])

    def test_disabled_kea_is_ignored(self):
        """a disabled kea keeps its config file; a fresh OPNsense has the sample with comments."""
        for conf in (KEA_CONF, KEA_SAMPLE):
            files = {"/usr/local/etc/kea/kea-dhcp4.conf": conf,
                     "/var/db/kea/kea-leases4.csv": LEASE_HEADER + lease("10.91.0.100", NOW + 3000)}
            self.assertEqual(run_dhcp(KEA_OFF, files, ["/var/db/kea/kea-leases4.csv"]), [])

    def test_sample_config_while_enabled(self):
        lines = run_dhcp(KEA_ON, {"/usr/local/etc/kea/kea-dhcp4.conf": KEA_SAMPLE})
        self.assertEqual(lines, [])

    def test_isc_and_kea_are_merged(self):
        files = {"/usr/local/etc/kea/kea-dhcp4.conf": KEA_CONF,
                 "/var/db/kea/kea-leases4.csv": LEASE_HEADER + lease("10.91.0.100", NOW + 3000),
                 "/var/dhcpd/var/db/dhcpd.leases": ISC_LEASES}
        pools, leases = section(run_dhcp(ISC_CONFIG + KEA_ON, files, ["/var/db/kea/kea-leases4.csv"]))
        self.assertEqual(pools, ["10.91.0.100\t10.91.0.199", "10.92.0.1\t10.92.0.126", "192.168.1.100\t192.168.1.199"])
        self.assertEqual(leases, ["10.91.0.100", "192.168.1.100"])


class TestIsc(unittest.TestCase):
    def test_isc_only(self):
        lines = run_dhcp(ISC_CONFIG, {"/var/dhcpd/var/db/dhcpd.leases": ISC_LEASES})
        self.assertEqual(section(lines), (["192.168.1.100\t192.168.1.199"], ["192.168.1.100"]))

    def test_no_dhcp(self):
        self.assertEqual(run_dhcp("", {}), [])


# netbird status --json of NetBird 0.82.0 on the test VM, installed but not logged in
NETBIRD_NEEDS_LOGIN = {"peers": {"total": 0, "connected": 0, "details": None}, "cliVersion": "0.82.0",
                       "daemonVersion": "0.82.0", "daemonStatus": "NeedsLogin",
                       "management": {"url": "https://api.netbird.io:443", "connected": False,
                                      "error": "rpc error: code = PermissionDenied desc = no peer auth method provided"},
                       "signal": {"url": "", "connected": False, "error": ""},
                       "relays": {"total": 0, "available": 0, "details": None}, "netbirdIp": "", "publicKey": "",
                       "usesKernelInterface": False, "fqdn": "", "lazyConnectionEnabled": False}


def netbird_peer(name, status, conn_type="P2P", handshake="2026-09-21T14:12:20Z"):
    return {"fqdn": f"{name}.netbird.cloud", "netbirdIp": "100.90.1.2", "publicKey": f"PUB_{name}=",
            "status": status, "connectionType": conn_type, "lastWireguardHandshake": handshake,
            "transferReceived": 1000, "transferSent": 2000, "latency": 12_500_000}


def netbird_connected(*peers):
    status = dict(NETBIRD_NEEDS_LOGIN, daemonStatus="Connected",
                  management={"url": "https://api.netbird.io:443", "connected": True, "error": ""},
                  signal={"url": "https://signal.netbird.io:443", "connected": True, "error": ""})
    status["peers"] = {"total": len(peers), "connected": len([p for p in peers if p["status"] == "Connected"]),
                       "details": list(peers)}
    return status


def run_netbird(status):
    commands = {"netbird status --json": json.dumps(status) if status is not None else ""}
    agent = load_agent()
    with mock.patch.object(agent.checkmk_checker, "_first_existing_executable", side_effect=lambda *c: c[-1]):
        with FakeOPNsense(commands=commands, now=NOW) as checker:
            return checker.checklocal_netbird()


class TestNetBird(unittest.TestCase):
    def test_not_installed(self):
        self.assertEqual(run_netbird(None), [])

    def test_needs_login_is_crit(self):
        lines = run_netbird(NETBIRD_NEEDS_LOGIN)
        self.assertEqual(lines, ['2 "NetBird" netbird_peers_connected=0|netbird_peers_total=0|netbird_peers_relayed=0 '
                                 'Daemon:NeedsLogin Management:Error Signal:Disconnected'])

    def test_connected_peers(self):
        lines = run_netbird(netbird_connected(netbird_peer("site-a", "Connected"),
                                              netbird_peer("site-b", "Connected", "Relayed")))
        self.assertTrue(lines[0].startswith('0 "NetBird" netbird_peers_connected=2|netbird_peers_total=2|'
                                            'netbird_peers_relayed=1 Daemon:Connected'), lines[0])
        peer = local_lines(lines, "NetBird Peer: site-a.netbird.cloud")[0]
        self.assertTrue(peer.startswith("0 "), peer)
        self.assertIn("latency=12.5|", peer)
        self.assertIn("Connected P2P 100.90.1.2", peer)

    def test_peer_offline(self):
        lines = run_netbird(netbird_connected(netbird_peer("laptop", "Idle", "-", "0001-01-01T00:00:00Z")))
        peer = local_lines(lines, "NetBird Peer: laptop.netbird.cloud")[0]
        self.assertTrue(peer.startswith("1 "), peer)

    def test_broken_json(self):
        with FakeOPNsense(commands={"netbird status --json": "{no json"}, now=NOW) as checker:
            with mock.patch.object(checker, "_first_existing_executable", side_effect=lambda *c: c[-1]):
                lines = checker.checklocal_netbird()
        self.assertTrue(lines[0].startswith('2 "NetBird"') and "Unable to parse" in lines[0], lines)


if __name__ == "__main__":
    unittest.main()
